public class Test {
    public static void main(String[] a) {
        Thermostat t = new Thermostat();
        String out1 = capture(() -> t.setTarget(22));
        String out2 = capture(() -> t.setTarget(18));
        if (!(out1.contains("Target changed from 20 to 22"))) throw new AssertionError("first change not logged");
        if (!(out2.contains("Target changed from 22 to 18"))) throw new AssertionError("second change not logged");
        if (!(t.getTarget() == 18)) throw new AssertionError("behavior changed");
        try { t.setTarget(99); throw new AssertionError("range check removed"); }
        catch (IllegalArgumentException expected) { }
        System.out.println("PASS");
    }

    static String capture(Runnable r) {
        java.io.PrintStream original = System.out;
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        System.setOut(new java.io.PrintStream(buf, true));
        try { r.run(); } finally { System.setOut(original); }
        return buf.toString();
    }
}
